                "• ეს ტერმინი აღნიშნავს ბიზანტიისა და მისი გავლენის ქვეშ მყოფი სახელმწიფოების ერთობას. თანამეგობრობის საზღვრები გაცილებით ფართო იყო, ვიდრე თავად იმპერიისა.\n• მასში შემავალი ხალხები ბიზანტიის იმპერატორთან და კონსტანტინოპოლის საპატრიარქოსთან სხვადასხვა გზით იყვნენ დაკავშირებული. მათ საერთო რელიგიური და კულტურული სივრცე ჰქონდათ, მაგრამ ეს ყოველთვის არ ნიშნავდა პოლიტიკურ ერთობას.\n• შუა საუკუნეებში საქართველოც ამ თანამეგობრობის წევრი იყო.",
                "ქართულ-ბიზანტიური ურთიერთობა სამ პერიოდად შეიძლება დავყოთ:\n• V–VII საუკუნეები: ბიზანტიისა და სასანიანთა ირანის დაპირისპირების ხანა;\n• VIII–IX საუკუნეები: არაბების დასუსტების შემდეგ ქართული სამეფო-სამთავროების შექმნის პერიოდი;\n• X საუკუნიდან: საქართველოს გაერთიანების შემდგომი ხანა.",
