                "• VIII–X საუკუნეებში ჩრდილოეთ იტალიაზე გერმანული სამეფოები იბრძოდნენ. ამიტომ პაპებს თავიანთი სახელმწიფოს დასაცავად ძლიერი მფარველი სჭირდებოდათ. VIII საუკუნის მეორე ნახევარში მფარველი ფრანკთა სამეფო გახდა. სამაგიეროდ პაპმა კარლოს დიდს იმპერატორის ტიტული უბოძა, ტიტულთან ერთად კი კარლოსმა ეპისკოპოსების დანიშვნის უფლებაც მიიღო.\n• კარლოს დიდის სიკვდილის შემდეგ იმპერია მის შთამომავლებს შორის გაიყო. თანდათან ჩამოყალიბდა სამი ხალხის, ფრანგების, იტალიელებისა და გერმანელების, საცხოვრებელი სივრცე.\n• 962 წელს პაპმა გერმანიის მეფე ოტონ I იმპერატორად აკურთხა. ამის შემდეგ გერმანიას „საღვთო რომის იმპერია“ ეწოდა. იმპერატორის ტიტული მხოლოდ გერმანელ მეფეებს ჰქონდათ. ყოველი ახალი მეფე ალპებს გადადიოდა და გვირგვინს რომში პაპისგან იღებდა.",
