                "• ეკლესიას მტრის დასამარცხებლად ჯარი არ სჭირდებოდა. მისი იარაღი განკვეთა და ინტერდიქტი იყო.\n• განკვეთა (უმძიმეს შემთხვევაში ანათემა) ადამიანს ქრისტიანული ეკლესიის წევრის ყველა უფლებას ართმევდა. ის ვეღარ მონაწილეობდა წესებსა და საიდუმლოებებში, სხვა ქრისტიანებს კი მასთან ურთიერთობა უნდა გაეწყვიტათ. ფაქტობრივად, ეს სამოქალაქო სიკვდილს ნიშნავდა. ეკლესია განკვეთას XI საუკუნემდეც იყენებდა, მაგრამ იმპერატორი პირველად გრიგოლ VII-ემ განკვეთა.\n• თუ სასჯელი მთელ სოფელს, ქალაქს ან ქვეყანას ეხებოდა, მას ინტერდიქტი ერქვა. ამ დროს ყველა ქრისტიანული წესი იკრძალებოდა: არ შეიძლებოდა ნათლობა, ქორწინება ან დაკრძალვა ქრისტიანული წესით.",
