                "• პაპის მოწოდებას არცერთი ევროპელი მონარქი არ გამოეხმაურა, მაგრამ მასში მრავალი დიდი ფეოდალი, ჰერცოგი და გრაფი მონაწილეობდა: ჰერცოგი გოტფრიდ ბულონელი და მისი ძმა ბალდუინი, გრაფი რაიმუნდ ტულუზელი, ბოემუნდ ტარენტელი, ინგლისის მეფის ძმა რობერტი, საფრანგეთის მეფის ძმა ჰუგო და სხვები. ზოგმა წასვლამდე მამულიც გაყიდა.\n• 1096 წელს ოთხი ძირითადი ჯარი დაიძრა. 1097 წელს ისინი კონსტანტინოპოლში შეიკრიბნენ. ალექსი კომნენოსმა მეთაურებს ერთგულების ფიცი დაადებინა და ურჩია, როგორ ებრძოლათ თურქებთან. ანა კომნენე „ალექსიადაში“ ჯვაროსნებს „ლათინებს“ უწოდებს და აღწერს მათ ქედმაღლობას: ერთი გრაფი იმპერატორის ტახტზეც კი დაჯდა.\n• ჯვაროსნებმა ნიკეა აიღეს და დორილეონთან თურქები სასტიკად დაამარცხეს. ეს მათი პირველი დიდი გამარჯვება იყო. 1098 წელს მათ სირიის უმნიშვნელოვანესი ქალაქი, ანტიოქია, აიღეს.\n• ლაშქრობაში იტალიური ქალაქ-რესპუბლიკებიც მონაწილეობდნენ. გენუის ფლოტის მხარდაჭერამ დიდწილად განსაზღვრა წარმატება.",
                "• 1099 წლის ივლისში ჯვაროსნებმა იერუსალიმი აიღეს (ამ დროისთვის ქალაქი სელჩუკებს უკვე ეგვიპტის ფატიმიანებმა წაართვეს, 1098 წ.). ქრისტიანი და მუსლიმი ავტორები (იტალიურ-ნორმანდიული ქრონიკა, იბნ ალ-ასირი) ერთნაირად აღწერენ, რომ ქალაქის მოსახლეობას დღეების განმავლობაში ხოცავდნენ, მაგრამ მოვლენებს სხვადასხვაგვარად აფასებენ.\n• იერუსალიმის აღების შემდეგ ჯვაროსნებმა ქალაქის მმართველად გოტფრიდ ბულონელი აირჩიეს, მაგრამ მან მეფის ტიტულზე უარი თქვა. გადმოცემით, მან თქვა, რომ არ დაიდგამდა ოქროს გვირგვინს იქ, სადაც ქრისტემ ეკლის გვირგვინი ატარა. ამიტომ თავს „წმინდა საფლავის დამცველი“ უწოდა.\n• გოტფრიდი 1100 წლის ივლისში გარდაიცვალა. ტახტზე მისი ძმა, ედესის გრაფი ბალდუინი, ავიდა. მან მეფის ტიტული მიიღო და 1100 წლის შობას ბეთლემში ბალდუინ I სახელით აკურთხეს. ის იერუსალიმის სამეფოს პირველი მეფე გახდა.",
