                "• მეფე ჯონმა ქარტიას ხელი მოაწერა, მაგრამ თავისი უფლებების შეზღუდვას ვერ შეეგუა და მის შესრულებაზე უარი თქვა. მეფესა და ფეოდალებს შორის დაპირისპირება შემდგომშიც გაგრძელდა.\n• 1265 წელს ბარონებმა სიმონ დე მონფორის მეთაურობით დაამარცხეს მეფე (მაშინ უკვე ჰენრი III მეფობდა). მალე მონფორის ინიციატივით პირველი პარლამენტი შეიკრიბა.\n• პარლამენტში შედიოდნენ ბარონები, ეპისკოპოსები, აბატები და თითო საგრაფოდან ორ-ორი რაინდი, მნიშვნელოვანი ქალაქებიდან კი ორ-ორი დეპუტატი. ამიერიდან მეფეს ახალი გადასახადის დაწესება მხოლოდ პარლამენტის თანხმობით შეეძლო.\n• პარლამენტი წოდებრივ-წარმომადგენლობითი ორგანო იყო: პირველი წოდება — უმაღლესი სასულიერო პირები, მეორე — არისტოკრატია (ჰერცოგები, მარკიზები, გრაფები, ბარონები), მესამე — საგრაფოებისა და ქალაქების არჩეული წარმომადგენლები. მესამე წოდებისგან შემდგომში თემთა (ქვედა) პალატა ჩამოყალიბდა, პირველი ორისგან — ლორდთა (ზედა) პალატა.",
