                "• სამხედრო რეფორმის შემდეგ ჩინგიზ-ყაენმა დაპყრობითი ომები დაიწყო. ქვეყანაზე თავდასხმამდე ინფორმაციას ვაჭრებისგან აგროვებდა და ჯარს ამზადებდა.\n• 1211 წელს მონღოლებმა მეზობელ ჩინეთზე ილაშქრეს: აიღეს დედაქალაქი პეკინი, ცინის დინასტია დაამხეს და მისი ტერიტორია დაიმორჩილეს.\n• ჩინელებისგან მონღოლებმა ციხის ასაღები ტექნიკა — ქვასატყორცნები, კიბეები, ტარანები — გადაიღეს და მალე ციხე-ქალაქების აღების დიდოსტატები გახდნენ.\n• შემდეგ მონღოლები დასავლეთისკენ დაიძრნენ და შუა აზიის უდიდესი სახელმწიფო — ხორეზმი — დაიპყრეს.\n• მონღოლების სახელი სხვა ქვეყნებში შიშს იწვევდა. ეს განზრახ ხდებოდა: მათ შესახებ საუკუნეების განმავლობაში არავინ არაფერი იცოდა, თავად კი დაპყრობილ ქალაქებში თავიანთი სისასტიკის ამბებს ავრცელებდნენ.",
