                "• თამარის ვაჟი, გიორგი IV ლაშა, 1213–1223 წლებში მეფობდა. მემატიანეები მას განსხვავებულად აფასებენ, ისტორიკოსებიც ერთმანეთისგან განსხვავებულ აზრს გამოთქვამენ.\n• ლაშა-გიორგის თანამედროვე მემატიანე მას აქებს: ის იყო „ლომი ძალითა“, ყველა ადამიანის — დიდისა და მცირის — მოყვარული, მშვიდი, კარგი მშვილდოსანი და ცხენოსანი, „ომში დავით პაპის პაპის სწორი“, ლაშქრობის მცოდნე, გაჭირვებულთა განმკითხველი, ბჭე და მოსამართლე.\n• XIV საუკუნის ავტორი, ჟამთააღმწერელი, სხვაგვარად ახასიათებს: მხნე და ძლიერი, მაგრამ ლაღი, ამპარტავანი, ჯიუტი, მუსიკისა და ნადიმების მოყვარე. მისი ცნობით, მეფემ დედის ვაზირები ჩამოიშორა და ის თანატოლები დაიახლოვა, რომლებთან ერთადაც ლხინობდა — ამას კათალიკოსი და დიდებულები ვერ იტანდნენ.\n• ჟამთააღმწერლის ცნობითვე, მეფემ ერთი აზნაურის ცოლი შეიყვარა და კარზე მოიყვანა; მისგან ვაჟი, დავითი, შეეძინა. კათალიკოსმა, ეპისკოპოსებმა და ვაზირებმა მოითხოვეს, რომ ქალი ქმარს დაბრუნებოდა. ასეც მოხდა, ლაშა-გიორგი კი უქორწინებელი დარჩა.",
