                "• ივანე ჯავახიშვილის აზრით, ფუფუნებაში გაზრდილმა უფლისწულმა დედის ერთგული ვაზირების ნაცვლად თანატოლები დაიახლოვა, თუმცა სახელმწიფოებრივი ალღო გამოიჩინა და საქართველოს ყველა მონაპოვრის შენარჩუნება შეძლო. ის არ ერიდებოდა რწმენისა და ზნეობის წესების დარღვევას.\n• შოთა ბადრიძე სვამს კითხვას: საიდან მომდინარეობს ლაშაზე ასეთი უარყოფითი ცნობები? მისი აზრით, ლაშას დიდებულებთან შინაპოლიტიკური ბრძოლა ჰქონდა: ცდილობდა, ივანე ათაბაგისა და სხვა სამხედრო ხელისუფალთა გავლენისგან განთავისუფლებულიყო და თამარის დროინდელი დიდებულების ნაცვლად ახალგაზრდა მეომრებს ეყრდნობოდა.\n• ნიკო ბერძენიშვილის აზრით, ლაშა-გიორგი ცდილობდა, ერთგვარი რეფორმით შეეზღუდა დიდგვაროვანთა პოლიტიკური წრეები, რომლებიც ძალიან გაძლიერებულები იყვნენ.\n• ერთსა და იმავე პიროვნებას ავტორები განსხვავებულად აფასებენ — ამიტომ ისტორიკოსი წყაროებს ერთმანეთს ადარებს და ავტორის პოზიციასაც ითვალისწინებს.",
